#!/bin/sh
# Builds Smaragd Dash: graphics, caves and music are generated by the Python tools
# in tools/, the moves for the screencast by tools/solve.c; then everything is
# compiled into build/smaragd-dash.prg, which goes onto the disk image
# build/smaragd-dash.d81 together with the tiles (build/gen/tiles.bin as
# SMARAGD.TILES), the title logo (build/gen/logo.bin as SMARAGD.LOGO), the
# editor's code (build/gen/edit.prg as SMARAGD.EDIT, see link.ld), GDash's
# engine, which plays all caves (build/gdengine.bin as SMARAGD.GD, gdengine.ld)
# and the calls into it (SMARAGD.LOW), the
# caves (build/caves/caveNN-L.bin as CAVENN-L: cave and level), the
# high scores (SMARAGD.SCORES), the slots for the caves of the editor
# (build/caves/ownNN.bin as OWNNN and ownNN-L.bin as OWNNN-L for their other
# levels, empty); the screencast build
# (-DSCREENCAST) gets its moves as well (demoNN.bin as DEMONN). The high
# scores and the slots are kept from the old disk. The game loads them from that
# disk. The version is in the file VERSION: on the title and in the disk's
# name ("SMARAGD 1.0.1": a disk name has at most 16 characters).
# Called by .vscode/run-current.sh with the compiler in $MEGA65_CC.

set -e
cd "$(dirname "$0")"
CC=${MEGA65_CC:-../toolchain/llvm-mos/bin/mos-mega65-clang}
VERSION=$(cat VERSION)

# build/gen is compiled into the game, so nothing old may stay there
rm -rf build/gen build/caves
mkdir -p build/gen build/caves
python3 tools/mkgfx.py build/gen build/preview.png
python3 tools/mkcave.py build/caves build/gen caves/*.bd
python3 tools/mkmusic.py build/gen
printf '// Generated by build.sh from VERSION - do not edit\n#define VERSION "%s"\n' "$VERSION" \
    > build/gen/version.h
# The moves for the screencast build (main.c, SCREENCAST), found with
# GDash's engine on the host: build/caves/demoNN.bin, on the disk as DEMONN.
# Every build runs the solver: it names any cave it finds no way through.
${HOST_CC:-cc} -O2 -Wall -Wno-array-bounds -Isrc -Ibuild/gen -Ibuild/caves -o build/solve \
    tools/solve.c build/caves/caves.c build/gen/gdcave.c
build/solve build/gen build/caves
# shellcheck disable=SC2086
# The program: all but GDash's engine (src/gdengine.c, build/gen/gdcave.c),
# which is linked on its own below
set --
for f in src/*.c src/gdfar.s src/render.s src/text.s src/music.s src/sound.s src/cover.s build/gen/*.c; do
    case "$f" in
        src/gdengine.c | build/gen/gdcave.c) ;;
        *) set -- "$@" "$f" ;;
    esac
done
"$CC" -Os -g -Wall $SMARAGD_CFLAGS -Isrc -Ibuild/gen -o build/smaragd-dash.prg \
    -T link.ld -Wl,-Map=build/smaragd-dash.map "$@"
# The editor's code, an overlay (link.ld): on the disk as SMARAGD.EDIT; the
# calls into GDash's engine: SMARAGD.LOW
OBJCOPY=${MEGA65_OBJCOPY:-../toolchain/llvm-mos/bin/llvm-objcopy}
"$OBJCOPY" -O binary --only-section=.editor build/smaragd-dash.prg.elf build/gen/editor.bin
{ printf '\000\000'; cat build/gen/editor.bin; } > build/gen/edit.prg
"$OBJCOPY" -O binary --only-section=.lowcode build/smaragd-dash.prg.elf build/gen/lowcode.bin
{ printf '\000\000'; cat build/gen/lowcode.bin; } > build/gen/low.prg
# GDash's engine on its own (gdengine.ld; what it shares with the program:
# shared.ld): on the disk as SMARAGD.GD
"$CC" -Os -g -Wall -DGD_FAR $SMARAGD_CFLAGS -Isrc -Ibuild/gen -nostartfiles -T gdengine.ld \
    -Wl,-Map=build/gdengine.map -o build/gdengine.bin src/gdengine.c src/gdjump.s src/gdscan.s src/gdcell.s build/gen/gdcave.c
{ printf '\000\000'; cat build/gdengine.bin; } > build/gen/gd.prg
# The caves; the moves only for the screencast build, which loads them -
# those of the caves it plays, -DDEMO_FIRST to -DDEMO_LAST of the caves with
# moves (the disk has no room for all) -, and those of the demo caves for its
# -DTOUR build (tools/record-tour.sh)
case " $MEGA65_CFLAGS $SMARAGD_CFLAGS " in
    *" -DSCREENCAST "*) DEMOS=yes ;;
    *) DEMOS=no ;;
esac
DEMO_FIRST=$(echo " $MEGA65_CFLAGS $SMARAGD_CFLAGS " | sed -n 's/.* -DDEMO_FIRST=\([0-9]*\) .*/\1/p')
DEMO_LAST=$(echo " $MEGA65_CFLAGS $SMARAGD_CFLAGS " | sed -n 's/.* -DDEMO_LAST=\([0-9]*\) .*/\1/p')
DEMO_N=0
set --
case " $MEGA65_CFLAGS $SMARAGD_CFLAGS " in
    *" -DTOUR "*)
        for f in build/tour/tour*.bin; do
            [ -f "$f" ] && set -- "$@" "$f=$(basename "$f" .bin)"
        done ;;
esac
# The builds that play the slots only (-DTOUR, -DGDCHECK) leave the game's
# caves out: the disk has room for their files then
CAVES=yes
case " $MEGA65_CFLAGS $SMARAGD_CFLAGS " in
    *" -DTOUR "* | *" -DGDCHECK "*) CAVES=no ;;
esac
# The check build (-DGDCHECK, tests/test_gdmega65.py): a file of moves for
# each slot, CHECK01 ..., empty (3 blocks), which the test fills
case " $MEGA65_CFLAGS $SMARAGD_CFLAGS " in
    *" -DGDCHECK "*)
        head -c 762 /dev/zero > build/gen/check.bin
        for n in $(seq -w 1 20); do
            set -- "$@" "build/gen/check.bin=CHECK$n"
        done ;;
esac
# The game's caves in the partition CAVES; the own caves' slots in the
# partitions OWN1 ... (a game each, renamed in the editor), kept from the
# old disk
GAMES=3
KEEP="--keep SMARAGD.SCORES"
for f in build/caves/*.bin; do
    name=$(basename "$f" .bin)
    case "$f" in
        build/caves/demo*)
            DEMO_N=$((DEMO_N + 1))
            [ $DEMOS = yes ] && [ $DEMO_N -ge "${DEMO_FIRST:-1}" ] && [ $DEMO_N -le "${DEMO_LAST:-99}" ] &&
                set -- "$@" "$f=$name" ;;
        build/caves/cave*) [ $CAVES = yes ] && set -- "$@" "$f=CAVES/$name" ;;
        build/caves/own*)
            for g in $(seq 1 $GAMES); do
                KEEP="$KEEP --keep OWN$g/$name"
                set -- "$@" "$f=OWN$g/$name"
            done ;;
    esac
done
# The high score table: one sector of zeros, which the game reads as the
# default table and overwrites (src/hiscore.c); a new build keeps the one
# on the old disk.
head -c 254 /dev/zero > build/gen/scores.bin
# shellcheck disable=SC2086
../toolchain/tools/bin/mkd81.py $KEEP build/smaragd-dash.d81 "SMARAGD $VERSION" \
    "build/smaragd-dash.prg=SMARAGD DASH" "build/gen/pal.bin=SMARAGD.PAL" "build/gen/tiles.bin=SMARAGD.TILES" \
    "build/gen/logo.bin=SMARAGD.LOGO" "build/gen/edit.prg=SMARAGD.EDIT" \
    "build/gen/low.prg=SMARAGD.LOW" "build/gen/gd.prg=SMARAGD.GD" \
    "build/gen/scores.bin=SMARAGD.SCORES" "$@"
